<?php
require_once __DIR__.'/includes/functions.php';require_role(['admin']);$page_title='Administration';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['resource_id']??0);$action=$_POST['action']??'';if(in_array($action,['approved','rejected'],true)){$s=$pdo->prepare("UPDATE resources SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status='pending'");$s->execute([$action,current_user()['id'],$id]);log_activity($pdo,current_user()['id'],'resource_'.$action,$id);flash('success','Resource review updated.');}redirect('admin.php');}
$pending=$pdo->query("SELECT r.*,u.name uploader,d.name department_name,s.code subject_code FROM resources r JOIN users u ON u.id=r.uploaded_by LEFT JOIN departments d ON d.id=r.department_id LEFT JOIN subjects s ON s.id=r.subject_id WHERE r.status='pending' ORDER BY r.created_at")->fetchAll();
$counts=['users'=>$pdo->query("SELECT COUNT(*) FROM users")->fetchColumn(),'resources'=>$pdo->query("SELECT COUNT(*) FROM resources")->fetchColumn(),'approved'=>$pdo->query("SELECT COUNT(*) FROM resources WHERE status='approved'")->fetchColumn(),'pending'=>$pdo->query("SELECT COUNT(*) FROM resources WHERE status='pending'")->fetchColumn()];
require __DIR__.'/includes/header.php';?>
<section class="page-heading"><span class="eyebrow">ADMINISTRATION</span><h1>Content review</h1><p>Review community contributions before they appear in the public library.</p></section>
<div class="stats-grid"><div class="stat-card"><span>Total users</span><b><?= (int)$counts['users'] ?></b></div><div class="stat-card"><span>Total resources</span><b><?= (int)$counts['resources'] ?></b></div><div class="stat-card"><span>Published</span><b><?= (int)$counts['approved'] ?></b></div><div class="stat-card"><span>Awaiting review</span><b><?= (int)$counts['pending'] ?></b></div></div>
<div class="section-head"><div><h2>Pending submissions</h2><p>Check the document and its academic metadata.</p></div><a class="btn light" href="<?= url('reports.php') ?>">View reports</a></div>
<div class="table-wrap"><table><thead><tr><th>Resource</th><th>Contributor</th><th>Category</th><th>Department / subject</th><th>Submitted</th><th>Actions</th></tr></thead><tbody><?php foreach($pending as $r): ?><tr><td><a href="<?= url('resource.php?id='.$r['id']) ?>"><?= e($r['title']) ?></a><br><small><?= e($r['original_name']) ?></small></td><td><?= e($r['uploader']) ?></td><td><?= e(str_replace('_',' ',$r['type'])) ?></td><td><?= e($r['department_name']??'—') ?> <?= e($r['subject_code']??'') ?></td><td><?= e(date('d M Y',strtotime($r['created_at']))) ?></td><td><div class="inline-actions"><form method="post"><?= csrf_field() ?><input type="hidden" name="resource_id" value="<?= $r['id'] ?>"><button class="btn tiny primary" name="action" value="approved">Approve</button></form><form method="post"><?= csrf_field() ?><input type="hidden" name="resource_id" value="<?= $r['id'] ?>"><button class="btn tiny danger" name="action" value="rejected">Reject</button></form></div></td></tr><?php endforeach; if(!$pending): ?><tr><td colspan="6">No pending submissions. You're all caught up.</td></tr><?php endif; ?></tbody></table></div>
<?php require __DIR__.'/includes/footer.php';?>